<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Registration confirmed</title><style>body{margin:0;background:#f4f7fb;font:15px Arial;color:#18243a}.card{max-width:650px;margin:60px auto;background:#fff;border:1px solid #dfe7f1;border-radius:16px;padding:34px;box-shadow:0 15px 40px #1c2d4812}.ok{width:58px;height:58px;border-radius:50%;background:#dff7ec;color:#07845c;display:grid;place-items:center;font-size:28px}.row{display:flex;justify-content:space-between;border-top:1px solid #edf1f5;padding:12px 0}.muted{color:#718096}.button{display:inline-block;background:#377dff;color:#fff;padding:11px 16px;border-radius:8px;text-decoration:none}</style></head><body><main class="card"><div class="ok">✓</div><h1>Registration confirmed</h1><p class="muted">A place has been reserved for you at <b>{{$order->event->title}}</b>.</p><div class="row"><span>Order number</span><b>{{$order->order_number}}</b></div><div class="row"><span>Date</span><b>{{$order->event->starts_at->format('d M Y, h:i A')}}</b></div><div class="row"><span>Seats</span><b>{{$order->seat_count}}</b></div>@foreach($order->items as $item)<div class="row"><span>{{$item->quantity}} × {{$item->name}}</span><b>{{$order->currency}} {{number_format((float)$item->line_total,2)}}</b></div>@endforeach<div class="row"><strong>Total paid</strong><strong>{{$order->currency}} {{number_format((float)$order->total_amount,2)}}</strong></div><p><a class="button" href="{{route('events.index')}}">Explore more events</a></p></main></body></html>
